-- 2026-10-21 user request: enrich all 200 synthetic employees; identity/Auth/history stay intact.
alter table public.team_member_scoring
  add column if not exists certifications jsonb not null default '[]'::jsonb,
  add column if not exists past_projects jsonb not null default '[]'::jsonb,
  add column if not exists capability_source text not null default 'UNSPECIFIED',
  add column if not exists capability_version text;

alter table public.team_member_scoring
  drop constraint if exists team_member_certifications_array,
  drop constraint if exists team_member_projects_array,
  drop constraint if exists team_member_capability_source,
  drop constraint if exists team_member_synthetic_complete;

alter table public.team_member_scoring
  add constraint team_member_certifications_array check (jsonb_typeof(certifications) = 'array'),
  add constraint team_member_projects_array check (jsonb_typeof(past_projects) = 'array'),
  add constraint team_member_capability_source check (capability_source in ('UNSPECIFIED', 'SYNTHETIC')),
  add constraint team_member_synthetic_complete check (capability_source <> 'SYNTHETIC' or (
    capability_version is not null and capability_version <> '' and
    jsonb_typeof(skills) = 'array' and jsonb_array_length(skills) > 0 and
    jsonb_typeof(availability) = 'array' and jsonb_array_length(availability) > 0 and
    jsonb_array_length(certifications) > 0 and jsonb_array_length(past_projects) > 0
  ));

