insert into public.team_member_scoring(member_id, org_id, role, grade, skills, availability,
  certifications, past_projects, capability_source, capability_version)
select m.id, m.org_id, p.role, p.grade, p.skills, p.availability,
  p.certifications, p.past_projects, p.capability_source, p.capability_version
from capabilities p
join public.team_members m on m.person_code = p.person_code and m.is_demo
join public.organizations o on o.id = m.org_id and o.id = 'db4c863c-cb6a-593d-93ff-709a17e0157a'::uuid
  and o.slug = 'org-01' and o.is_demo
on conflict (member_id) do update set
  role = excluded.role, grade = excluded.grade, skills = excluded.skills,
  availability = excluded.availability, certifications = excluded.certifications,
  past_projects = excluded.past_projects, capability_source = excluded.capability_source,
  capability_version = excluded.capability_version;

comment on column public.team_member_scoring.certifications is 'Employee certificates; synthetic entries are marked isDemo and reference synthetic evidence.';
comment on column public.team_member_scoring.past_projects is 'Individual project experience, separate from company bid qualifications.';
-- Existing organization-scoped SELECT policy and revoked write grants remain effective for the added columns.
